async function RefreshActivePage() {
  if (!state.repoPath || state.questType == null) {
    render();
    return;
  }
  try {
    const b = QuestBase();
    const ov = await FetchJson(`/api/dashboard/quest_overview?${Qs(b)}`);
    state.overview = ov;
    if (state.page === "overview") {
      state.runStatus = await FetchJson(`/api/dashboard/run_status?${Qs(b)}`);
    }
    switch (state.page) {
      case "overview":
        break;
      case "human":
        await RefreshHuman();
        break;
      case "diffs":
        await RefreshDiffs();
        break;
      case "agents":
        await RefreshQuestAgents();
        break;
      case "physicalplan":
        await RefreshPhysicalPlanIssues();
        break;
      case "slice":
        await RefreshSlicePage();
        break;
      default:
        break;
    }
    state.lastError = null;
    state.lastOkAt = new Date().toISOString();
  } catch (e) {
    state.lastError = String(e.message || e);
  }
  render();
}

function StartScheduler() {
  if (state.scheduler) state.scheduler.Stop();
}

