      a.textContent = `Slice ${String(s.slice_number).padStart(4, "0")}`;
      a.addEventListener("click", (ev) => {
        ev.preventDefault();
        state.page = "slice";
        state.sliceNumber = s.slice_number;
        state.subpage = state.subpage || "physicalplan";
        PushUrl();
        void RefreshActivePage();
      });
