/**
 * Pure helpers for dashboard shell (unit-tested with Node).
 */

const x_STORAGE_KEY = "conductor_dashboard.repo_path";

export function StorageRepoKey() {
  return x_STORAGE_KEY;
}

/**
 * Resolve which tracked repository path to use.
 * Precedence: valid query > valid stored > valid default > first tracked.
 * If query names a path that is not tracked, surface invalidQueryPath and fall back.
 */
export function ResolveRepositorySelection(
  queryRepoPath,
  storedRepoPath,
  defaultRepoPath,
  trackedPaths
) {
  const valid = new Set(trackedPaths);
  const isValid = (p) => p != null && String(p).length > 0 && valid.has(String(p));

  let invalidQueryPath = null;
  if (queryRepoPath != null && String(queryRepoPath).length > 0 && !isValid(queryRepoPath)) {
    invalidQueryPath = String(queryRepoPath);
  }

  if (isValid(queryRepoPath)) {
    return { repoPath: String(queryRepoPath), invalidQueryPath: null };
  }
  if (isValid(storedRepoPath)) {
    return { repoPath: String(storedRepoPath), invalidQueryPath };
  }
  if (isValid(defaultRepoPath)) {
    return { repoPath: String(defaultRepoPath), invalidQueryPath };
  }
  const first = trackedPaths.length ? trackedPaths[0] : null;
  return { repoPath: first, invalidQueryPath };
}

/**
 * Polls only while getVisible() is true; fires immediately when tab becomes visible again.
 */
export class RefreshScheduler {
  constructor(options) {
    this.m_intervalMs = options.intervalMs;
    this.m_onTick = options.onTick;
    this.m_getVisible = options.getVisible;
    this.m_timer = null;
    this.m_onVisibility = () => {
      if (this.m_getVisible()) {
        void this.m_onTick();
      }
    };
  }

  Start() {
    this.Stop();
    this.m_timer = setInterval(() => {
      if (this.m_getVisible()) {
        void this.m_onTick();
      }
    }, this.m_intervalMs);
    if (typeof document !== "undefined") {
      document.addEventListener("visibilitychange", this.m_onVisibility);
    }
  }

  Stop() {
    if (this.m_timer != null) {
      clearInterval(this.m_timer);
      this.m_timer = null;
    }
    if (typeof document !== "undefined") {
      document.removeEventListener("visibilitychange", this.m_onVisibility);
    }
  }
}

export function MergeRunBadge(overview, runStatus) {
  const overlay = overview?.execution_overlay_status ?? "none";
  const activeRun = runStatus?.active_run;
  if (overlay === "human_intervention") {
    return { label: "Human intervention required", variant: "hi" };
  }
  if (overlay === "paused") {
    const until = overview?.paused_until ?? runStatus?.paused_until;
    return {
      label: until ? `Paused until ${until}` : "Paused",
      variant: "paused",
    };
  }
  if (overlay === "running" || activeRun != null) {
    return { label: "Running", variant: "running" };
  }
  return { label: "Idle / Not running", variant: "idle" };
}

/**
 * Shared helpers for dashboard detail pages (unit-tested with Node).
 */

export function EscapeHtml(s) {
  if (s == null) return "";
  return String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

/**
 * Renders quest ``last_transition`` from API (legacy or metadata-backed).
 */
export function FormatQuestLastTransitionHtml(lt) {
  if (!lt) return "—";
  let body = `${EscapeHtml(lt.timestamp)}: ${EscapeHtml(lt.previous_state)} → ${EscapeHtml(
    lt.next_state
  )}`;
  if (lt.global_step != null) {
    body += ` <span class="dash-muted">(step ${EscapeHtml(String(lt.global_step))})</span>`;
  }
  if (lt.child_chain && lt.child_chain.length > 1) {
    const c = lt.child_chain[1];
    body += ` · slice: ${EscapeHtml(c.state_before)} → ${EscapeHtml(c.state_after)}`;
  }
  return body;
}

function RenderInlineMarkdown(text) {
  let out = EscapeHtml(text);
  out = out.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2">$1</a>');
  out = out.replace(/`([^`]+)`/g, "<code>$1</code>");
  out = out.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
  out = out.replace(/(^|[^*])\*([^*\n]+)\*(?!\*)/g, "$1<em>$2</em>");
  return out;
}

/**
 * Mirrors server `render_dashboard_markdown`: safe lightweight markdown rendering.
 */
export function MarkdownToSafeHtml(markdown) {
  if (markdown == null || markdown === "") {
    return '<div class="dashboard-markdown"></div>';
  }
  const lines = String(markdown).split(/\r?\n/);
  let html = "";
  let paragraph = [];
  let listItems = [];
  let inCode = false;
  let codeLines = [];

  const flushParagraph = () => {
    if (!paragraph.length) return;
    const joined = paragraph.map((line) => line.trim()).filter(Boolean).join(" ");
    if (joined) {
      html += `<p>${RenderInlineMarkdown(joined)}</p>`;
    }
    paragraph = [];
  };

  const flushList = () => {
    if (!listItems.length) return;
    html += `<ul>${listItems.join("")}</ul>`;
    listItems = [];
  };

  const flushCode = () => {
    html += `<pre><code>${EscapeHtml(codeLines.join("\n"))}</code></pre>`;
    codeLines = [];
  };

  for (const raw of lines) {
    const line = raw.replace(/\n$/, "");
    const stripped = line.trim();
    if (stripped.startsWith("```")) {
      flushParagraph();
      flushList();
      if (inCode) {
        flushCode();
        inCode = false;
      } else {
        inCode = true;
      }
      continue;
    }
    if (inCode) {
      codeLines.push(line);
      continue;
    }
    if (!stripped) {
      flushParagraph();
      flushList();
      continue;
    }
    if (stripped.startsWith("#")) {
      flushParagraph();
      flushList();
      const level = Math.min((stripped.match(/^#+/) || [""])[0].length, 6);
      const content = stripped.slice(level).trim();
      html += `<h${level}>${RenderInlineMarkdown(content)}</h${level}>`;
      continue;
    }
    if (stripped.startsWith("- ") || stripped.startsWith("* ")) {
      flushParagraph();
      listItems.push(`<li>${RenderInlineMarkdown(stripped.slice(2).trim())}</li>`);
      continue;
    }
    paragraph.push(line);
  }

  if (inCode) {
    flushCode();
  }
  flushParagraph();
  flushList();
  return `<div class="dashboard-markdown">${html}</div>`;
}

export function PlanFileStorageKey(repoPath, questType, questNumber, sliceNumber) {
  return `dash.planFile:v1|${repoPath}|${questType}|${questNumber}|${sliceNumber}`;
}

export function SelectPlanFile(filenames, storedName) {
  if (!filenames || filenames.length === 0) {
    return null;
  }
  if (storedName && filenames.includes(storedName)) {
    return storedName;
  }
  return filenames[0];
}

export function FileLabelForDiff(f) {
  if (!f) return "";
  if (f.path_before && f.path_before !== f.path) {
    return `${f.path_before} → ${f.path}`;
  }
  return f.path || "";
}

/**
 * Build grid rows for two-panel diff from API `rows` (see parse_unified_diff_to_rows).
 */
export function BuildDiffRowsHtml(rows) {
  if (!rows || !rows.length) {
    return "";
  }
  let html = "";
  for (const row of rows) {
    const k = row.kind;
    if (k === "hunk_header") {
      html += `<div class="dash-diff-hunk" role="presentation">${EscapeHtml(row.text || "")}</div>`;
      continue;
    }
    if (k === "context") {
      const o = row.old;
      const n = row.new;
      html += `<div class="dash-diff-row dash-diff-row--ctx">
        <div class="dash-diff-gutter">${o ? EscapeHtml(String(o.line_no)) : ""}</div>
        <div class="dash-diff-cell dash-diff-cell--old">${EscapeHtml(o ? o.text : "")}</div>
        <div class="dash-diff-gutter">${n ? EscapeHtml(String(n.line_no)) : ""}</div>
        <div class="dash-diff-cell dash-diff-cell--new">${EscapeHtml(n ? n.text : "")}</div>
      </div>`;
      continue;
    }
    if (k === "removal") {
      const o = row.old;
      html += `<div class="dash-diff-row dash-diff-row--del">
        <div class="dash-diff-gutter">${o ? EscapeHtml(String(o.line_no)) : ""}</div>
        <div class="dash-diff-cell dash-diff-cell--old dash-diff-cell--del">${EscapeHtml(
          o ? o.text : ""
        )}</div>
        <div class="dash-diff-gutter"></div>
        <div class="dash-diff-cell dash-diff-cell--new"></div>
      </div>`;
      continue;
    }
    if (k === "addition") {
      const n = row.new;
      html += `<div class="dash-diff-row dash-diff-row--add">
        <div class="dash-diff-gutter"></div>
        <div class="dash-diff-cell dash-diff-cell--old"></div>
        <div class="dash-diff-gutter">${n ? EscapeHtml(String(n.line_no)) : ""}</div>
        <div class="dash-diff-cell dash-diff-cell--new dash-diff-cell--add">${EscapeHtml(
          n ? n.text : ""
        )}</div>
      </div>`;
      continue;
    }
    html += `<div class="dash-diff-row dash-diff-row--other">
      <div class="dash-diff-span4">${EscapeHtml(row.text || "")}</div>
    </div>`;
  }
  return html;
}

