test("RefreshScheduler does not tick while hidden", async () => {
  let visible = false;
  let ticks = 0;
  const s = new RefreshScheduler({
    intervalMs: 20,
    getVisible: () => visible,
    onTick: async () => {
      ticks += 1;
    },
  });
  s.Start();
  await new Promise((r) => setTimeout(r, 100));
  assert.equal(ticks, 0);
  visible = true;
  await new Promise((r) => setTimeout(r, 120));
  assert.ok(ticks >= 1);
  s.Stop();
});

