  }</p>
    </header>
    ${
      issues.length === 0
        ? '<p class="dash-empty">No issues recorded in physicalplan_issues.md.</p>'
        : `<div class="dash-issue-list">${cards}</div>`
    }
    ${respBlock}
  `;
