        <div class="dash-issue-details">${MarkdownToSafeHtml(i.details || "")}</div>
        ${
          i.resolution_notes
            ? `<div class="dash-issue-resolution"><strong>Resolution</strong><div class="dash-md-muted">${MarkdownToSafeHtml(
                i.resolution_notes
              )}</div></div>`
